function PrimeArea() {
  const [section,setSection] = useState("Início");
  const [search,setSearch] = useState("");
  const [mobileNav,setMobileNav] = useState(false);
  const [weight,setWeight] = useState("120");
  const [roll,setRoll] = useState("90");
  const [hours,setHours] = useState("4");
  const [hourCost,setHourCost] = useState("1.5");
  const [waste,setWaste] = useState("10");
  const [profit,setProfit] = useState("70");
  const [fee,setFee] = useState("20");
  const [sales,setSales] = useState("0");
  const [expenses,setExpenses] = useState("0");
  const [productCost,setProductCost] = useState("0");
  const [filament,setFilament] = useState("0");
  const [target,setTarget] = useState("10000");
  const [tab,setTab] = useState("Visão geral");
  const filtered = useMemo(()=>categories.filter(c=>c[0].toLowerCase().includes(search.toLowerCase()) || c[1].toLowerCase().includes(search.toLowerCase())),[search]);
  const cost = ((Number(weight)||0)/1000*(Number(roll)||0))*(1+(Number(waste)||0)/100)+((Number(hours)||0)*(Number(hourCost)||0));
  const price = cost*(1+(Number(profit)||0)/100)/(1-(Number(fee)||0)/100 || 1);
  const title = section === "Biblioteca 3D" ? "Biblioteca" : section;
  const jump = (s:string) => { setSection(s); setMobileNav(false); window.scrollTo({top:0,behavior:"smooth"}); };
  const panel = "rounded-2xl border border-[#dce5ef] bg-white shadow-[0_12px_40px_rgba(0,0,0,.14)]";
  const button = "inline-flex items-center justify-center gap-2 rounded-xl bg-[#f28c28] px-4 py-3 text-sm font-extrabold text-[#17324d] transition-all duration-200 hover:-translate-y-0.5 hover:bg-[#ffad55] hover:shadow-[0_8px_28px_rgba(242,140,40,.18)]";
  const label = "mb-2 block text-sm font-semibold text-[#536b82]";
  const field = "w-full rounded-xl border border-[#dce5ef] bg-[#f5f8fc] px-3 py-3 text-sm text-[#17324d] outline-none transition focus:border-[#f28c28] focus:ring-2 focus:ring-[#f28c28]/15";
  const heading = (eyebrow:string,h:string,desc?:string) => <div className="mx-auto mb-8 max-w-4xl text-center"><p className="mb-2 text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">{eyebrow}</p><h2 className="text-3xl font-black tracking-tight text-[#17324d] sm:text-4xl">{h}</h2>{desc && <p className="mx-auto mt-3 max-w-3xl leading-7 text-[#60758a]">{desc}</p>}</div>;
  const linkButton = (href:string,text:string) => <a className={button} href={href} target={href.startsWith("http")?"_blank":undefined} rel={href.startsWith("http")?"noreferrer":undefined}>{text} <span aria-hidden>↗</span></a>;

  return <div className="min-h-screen bg-[#f4f7fb] text-[#17324d] md:flex">
    <aside className={`fixed inset-y-0 left-0 z-40 flex h-dvh w-[276px] flex-col overflow-y-auto overscroll-contain border-r border-white/10 bg-[#12385a] p-4 transition-transform duration-300 md:sticky md:top-0 md:h-screen md:translate-x-0 ${mobileNav?"translate-x-0":"-translate-x-full"}`}>
      <button onClick={()=>jump("Início")} className="mb-8 flex w-full items-center justify-center gap-3 px-2 pt-1 text-left"><img src={logoUrl} alt="Prime Projetos 3D" className="h-11 w-11 shrink-0 object-contain"/><span className="min-w-0 text-left leading-tight"><span className="block text-sm font-black tracking-wide text-white">PRIME</span><span className="mt-1 block text-[10px] font-bold uppercase tracking-[.12em] text-[#ffad55]">Projetos 3D</span></span></button>
      <div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.22em] text-[#8293a5]">Área do assinante</div>
      <nav className="flex flex-1 flex-col gap-1 overflow-y-auto">{nav.map(([name,icon])=><button key={name} onClick={()=>jump(name)} className={`group flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition-all duration-200 ${section===name?"bg-[#f28c28] text-black shadow-[0_6px_22px_rgba(242,140,40,.12)]":"text-zinc-400 hover:bg-white/[.06] hover:text-[#17324d]"}`}><span className="text-base transition-transform group-hover:scale-110">{icon}</span>{name}{section===name&&<span className="ml-auto h-1.5 w-1.5 rounded-full bg-black"/>}</button>)}</nav>
      <div className="mt-5 border-t border-white/10 px-3 pt-4"><p className="truncate text-xs text-[#70849a]">Área exclusiva Prime Projetos 3D</p><button onClick={()=>jump("Suporte")} className="mt-3 text-sm font-semibold text-[#ffad55] hover:underline">Precisa de ajuda? →</button></div>
    </aside>
    {mobileNav&&<button aria-label="Fechar menu" onClick={()=>setMobileNav(false)} className="fixed inset-0 z-30 bg-black/60 md:hidden"/>}
    <main className="min-w-0 flex-1">
      <header className="sticky top-0 z-20 flex items-center gap-3 border-b border-[#dce5ef] bg-white/95 px-4 py-4 backdrop-blur-xl sm:px-7">
        <button onClick={()=>setMobileNav(true)} className="rounded-lg border border-white/10 px-3 py-2 md:hidden" aria-label="Abrir menu">☰</button>
        <div className="min-w-0 flex-1"><p className="text-[10px] font-black uppercase tracking-[.16em] text-[#f28c28]">PRIME PROJETOS 3D <span className="text-zinc-600">/ ÁREA DE MEMBROS</span></p><h1 className="truncate text-lg font-bold sm:text-xl">{title}</h1></div>
        <label className="hidden w-full max-w-xs items-center gap-2 rounded-xl border border-white/10 bg-[#f5f8fc] px-3 py-2.5 focus-within:border-[#f28c28]/70 sm:flex"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar categoria..." className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-zinc-600"/></label>
        <span className="hidden rounded-full border border-[#f28c28]/20 bg-[#fff1e4] px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-[#f28c28] lg:inline-flex">Acesso liberado</span>
      </header>
      <div className="mx-auto max-w-[1500px] px-4 py-7 sm:px-7 sm:py-9">
        {section==="Leia antes de começar" && <div className="space-y-5 animate-in fade-in duration-300">
          {heading("LEIA ANTES DE COMEÇAR","Bem-vindo ao Prime Projetos 3D 👋","1 minuto de leitura pra você saber exatamente o que tem aqui.")}
          <section className={`${panel} border-[#f28c28]/40 p-5 sm:p-6`}><h3 className="text-center text-2xl font-extrabold">O que é o Prime Projetos 3D</h3><p className="mx-auto mt-3 max-w-5xl text-center leading-7 text-zinc-300">O Prime Projetos 3D é uma <b className="text-[#17324d]">biblioteca de arquivos STL já prontos, separados e organizados por categoria</b>. A gente não cria os modelos: reunimos arquivos que já existem, muitos vindos de repositórios abertos como <b>MakerWorld, Printables e Thingiverse</b>, e fizemos a parte chata por você: procurar, baixar, separar e organizar tudo em pastas, pra você ir direto pra impressora.</p>
            <div className="mt-5 grid gap-3 lg:grid-cols-3">{[
              ["✅ O que você recebe",["Milhares de arquivos prontos pra fatiar","Tudo organizado por pasta e categoria","Natal separado numa pasta só","Calculadora de custo e painel de vendas","Bônus pra precificar, fotografar e vender"]],
              ["❌ O que não é",["Não são modelos inéditos ou criados por nós","Não é um lançamento exclusivo de peças","A mesma peça pode existir em outros sites"]],
              ["💡 Por que vale a pena",["Você economiza horas procurando modelo um por um","Encontra tudo num lugar só, por categoria","Tem as ferramentas pra calcular preço e vender"]]
            ].map(([t,items])=><div key={String(t)} className="rounded-xl border border-white/[.08] bg-[#f5f8fc] p-4 transition duration-200 hover:border-[#f28c28]/30 hover:bg-[#edf3f9]"><h4 className="font-extrabold">{t}</h4><ul className="mt-3 space-y-2 text-sm leading-5 text-zinc-400">{(items as string[]).map(i=><li key={i} className="flex gap-2"><span className="text-[#f28c28]">•</span>{i}</li>)}</ul></div>)}</div>
          </section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">O QUE VOCÊ JÁ TEM NAS MÃOS</p><h3 className="mt-2 text-center text-xl font-extrabold">Quanto tempo isso te economiza</h3><div className="mt-4 grid grid-cols-2 gap-3 xl:grid-cols-4">{[["+90 mil","arquivos já separados por categoria"],["27","categorias prontas pra navegar"],["+400","modelos de Natal numa pasta só"],["6","bônus pra precificar, fotografar e vender"]].map(([n,t])=><div key={n} className="rounded-xl border border-[#dce5ef] bg-[#f5f8fc] p-4 text-center transition hover:-translate-y-1 hover:border-[#f28c28]/40"><div className="text-3xl font-black tracking-tight text-[#f28c28]">{n}</div><p className="mt-2 text-sm leading-5 text-zinc-400">{t}</p></div>)}</div><p className="mt-4 leading-7 text-zinc-300">Achar, baixar, testar e organizar esse volume de arquivos sozinho leva <b>semanas</b> de pesquisa em vários sites, um modelo por vez. Aqui você abre a categoria e já está tudo junto. Junto vêm as ferramentas que esses sites não têm: <b>calculadora de lucro por peça, calendário de produção de Natal, lista das 30 peças com preço sugerido e painel de vendas</b>.</p></section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">SUA PRIMEIRA VITÓRIA HOJE</p><h3 className="mt-2 text-center text-xl font-extrabold">Faça isso nas próximas 24 horas</h3><ol className="mt-4 space-y-3">{["Abra Natal e escolha 3 peças pequenas (bola, estrela, enfeite).","Imprima a primeira e coloque peso e tempo na Calculadora.","Tire a foto seguindo o Guia de Fotos e poste no seu WhatsApp ou Instagram."].map((s,i)=><li key={s} className="flex gap-3 rounded-xl bg-white/[.03] p-3"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#f28c28] font-black text-black">{i+1}</span><span className="self-center text-zinc-300">{s}</span></li>)}</ol><p className="mt-4 text-sm leading-6 text-zinc-400">Quem imprime e posta a primeira peça no primeiro dia é quem tira o maior proveito da biblioteca. O resultado vem de imprimir, não de ficar só olhando as pastas.</p></section>
          <section className={`${panel} flex flex-col gap-4 border-[#f28c28]/25 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6`}><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">TRAVOU EM ALGUMA COISA?</p><h3 className="mt-2 text-xl font-extrabold">Fale com a gente antes de desistir</h3><p className="mt-2 max-w-3xl leading-6 text-zinc-400">Não achou o modelo que queria, um link não abriu ou ficou em dúvida sobre como imprimir ou precificar? Manda um e-mail que a gente te ajuda a encontrar o arquivo certo e a começar.</p><p className="mt-2 text-xs text-zinc-500">Sua garantia de 7 dias continua valendo do mesmo jeito. Só pedimos a chance de te ajudar primeiro.</p></div>{linkButton("mailto:botelhoenzo7@gmail.com","✉ CHAMAR NO E-MAIL")}</section>
          <section className={`${panel} flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6`}><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">🎓 NUNCA IMPRIMIU UM ARQUIVO BAIXADO?</p><h3 className="mt-2 text-xl font-extrabold">Veja o passo a passo completo no Guia do Iniciante.</h3></div><button className={button} onClick={()=>jump("Guia do Iniciante")}>ABRIR GUIA →</button></section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">COMO USAR</p><h3 className="mt-2 text-center text-xl font-extrabold">Seu passo a passo</h3><ol className="mt-4 grid gap-3 md:grid-cols-2">{["Biblioteca 3D: escolha a categoria e baixe os arquivos pelo Google Drive.","Fatie e teste: imprima 1 unidade de cada modelo antes de anunciar.","Calculadora: veja quanto custa cada peça e por quanto vender.","Bônus: use o calendário de Natal, o Top 30 e o guia de fotos pra vender.","Administração: registre suas vendas e acompanhe o lucro."].map((t,i)=><li key={t} className="flex gap-3 rounded-xl bg-white/[.03] p-4"><span className="font-black text-[#f28c28]">0{i+1}</span><span className="text-sm leading-6 text-zinc-300">{t}</span></li>)}</ol><p className="mt-4 text-sm text-zinc-500">Não encontrou algo ou um link não abre? Fale com a gente na aba Suporte.</p><button onClick={()=>jump("Início")} className={`${button} mt-5`}>ENTENDI, VER A BIBLIOTECA →</button></section>
        </div>}
        {section==="Guia do Iniciante" && <div className="space-y-5 animate-in fade-in duration-300">{heading("GUIA DO INICIANTE","Do arquivo à peça pronta 🎓","Nunca imprimiu um arquivo baixado? Siga este passo a passo na ordem. Leva uns 10 minutos pra ler.")}<div className={`${panel} p-5 sm:p-7`}><p className="text-xs font-black uppercase tracking-widest text-[#f28c28]">NESTE GUIA</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{["Entenda os arquivos","Instale o programa da sua impressora","Passo a passo da primeira impressão","Como mandar pra impressora (por marca)","Modelos com várias peças e várias cores","Configurações seguras pra começar","Deu problema? Soluções rápidas","Dicionário do iniciante"].map((s,i)=><a href={`#guide-${i+1}`} key={s} className="rounded-lg border border-white/[.07] bg-white/[.025] p-3 text-sm text-zinc-300 transition hover:border-[#f28c28]/40 hover:text-[#f28c28]"><span className="mr-3 font-black text-[#f28c28]">0{i+1}</span>{s}</a>)}</div></div>
          {[
            ["Entenda os arquivos",<><p>Cada modelo da biblioteca fica numa pasta do Google Drive. Dentro dela você vai encontrar:</p><p><b>📷 Foto (.jpg / .png)</b> É só a prévia, pra você ver como a peça fica. <b>Não vai pra impressora.</b></p><p><b>🧊 .STL</b> O formato da peça. Abre em qualquer programa de impressão 3D. Você escolhe cor e configurações.</p><p><b>📦 .3MF</b> Um “projeto pronto”: pode trazer várias peças, as cores e as placas já organizadas. É o melhor formato quando existe.</p><p><b>🗜️ .ZIP / .RAR</b> Pasta compactada. Baixe e <b>descompacte</b> (botão direito → Extrair) antes de abrir.</p><p className="rounded-xl bg-[#f28c28]/10 p-3 text-sm text-[#ffe88a]">💡 Pelo celular você só vê as fotos. O arquivo de impressão (.STL ou .3MF) precisa ser aberto num programa no computador. Entre na área de membros pelo computador pra baixar com mais facilidade.</p></>],
            ["Instale o programa da sua impressora",<><p>A impressora não lê o arquivo .STL/.3MF direto. Antes ele passa por um programa chamado <b>fatiador</b>, que transforma a peça em camadas e cria as instruções de impressão. Todos esses são grátis:</p><p><b>Bambu Lab</b> (A1, A1 mini, P1S, X1...) ➜ <a className="text-[#f28c28] underline" href="https://bambulab.com/en/download/studio" target="_blank" rel="noreferrer">Bambu Studio</a>. Abre os .3mf da biblioteca com placas e cores certinhas.</p><p><b>Creality</b> (Ender, K1, K2, Hi...) ➜ <a className="text-[#f28c28] underline" href="https://www.creality.com/pages/download" target="_blank" rel="noreferrer">Creality Print</a> (ou OrcaSlicer).</p><p><b>Elegoo, Anycubic, Prusa, Sovol, outras</b> ➜ <a className="text-[#f28c28] underline" href="https://github.com/SoftFever/OrcaSlicer/releases" target="_blank" rel="noreferrer">OrcaSlicer</a> (funciona com quase todas) ou o programa da própria marca.</p><p><b>Qualquer impressora</b> ➜ <a className="text-[#f28c28] underline" href="https://ultimaker.com/software/ultimaker-cura/" target="_blank" rel="noreferrer">UltiMaker Cura</a> também funciona, mas às vezes abre só a primeira peça de um .3mf.</p><p>Na primeira vez que abrir o programa, ele pede pra escolher o modelo da sua impressora. Escolha certinho: é isso que deixa as configurações corretas.</p></>],
            ["Passo a passo da primeira impressão",<ol className="list-decimal space-y-2 pl-5"><li><b>Baixe o arquivo</b> .STL ou .3MF da pasta do modelo (no computador). Se vier .zip, descompacte.</li><li><b>Abra no fatiador:</b> arraste o arquivo pra dentro do programa, ou use Arquivo → Abrir / Importar. Se for .3mf, use Abrir projeto.</li><li><b>Escolha o filamento:</b> pra começar, use PLA. É o mais fácil.</li><li><b>Confira a posição:</b> a peça precisa estar apoiada na mesa pela parte mais plana.</li><li><b>Suporte:</b> só ligue se a peça tiver partes “no ar”. Articulados e brinquedos sensoriais normalmente são feitos pra imprimir sem suporte.</li><li><b>Fatie:</b> clique em Fatiar. O programa mostra o tempo e a quantidade de filamento (anote na Calculadora).</li><li><b>Mande pra impressora</b> (veja o passo 4).</li><li><b>Acompanhe a primeira camada.</b> Se ela grudar bem, o resto quase sempre dá certo.</li></ol>],
            ["Como mandar pra impressora",<><p><b>Bambu Lab (A1, A1 mini, P1S, X1)</b></p><ol className="list-decimal space-y-1 pl-5"><li>No Bambu Studio, entre com a mesma conta Bambu que está na impressora.</li><li>Clique em Fatiar placa e depois em Imprimir: ele envia pela internet direto pra impressora.</li><li>Sem Wi-Fi? Use Exportar G-code fatiado, salve no cartão microSD e coloque na impressora.</li><li>Com AMS, escolha qual filamento vai em cada cor antes de imprimir.</li></ol><p><b>Creality (Ender, K1, K2, Hi)</b></p><ol className="list-decimal space-y-1 pl-5"><li>No Creality Print, escolha seu modelo, fatie e clique em Imprimir.</li><li>K1, K2 e modelos com Wi-Fi: envie pela rede.</li><li>Ender e modelos sem Wi-Fi: exporte G-code, salve no cartão SD/pendrive e selecione no visor.</li><li>Creality Cloud funciona melhor com .STL. Se um .3mf abrir com peças faltando, fale com a gente.</li></ol><p><b>Outras marcas</b> (Elegoo, Anycubic, Prusa, Sovol...): no OrcaSlicer ou programa da marca, escolha a impressora, fatie, exporte G-code e salve no cartão SD/pendrive.</p></>],
            ["Modelos com várias peças e várias cores",<><p>Muitos modelos (ursinho com gorro, boneco de neve, Papai Noel) vêm em várias peças pra montar ou colar depois.</p><ul className="list-disc space-y-2 pl-5"><li><b>Placas:</b> num .3mf, as peças podem estar divididas em Placa 1, Placa 2... Confira todas.</li><li><b>Lista de objetos:</b> no lado direito do programa aparecem todas as peças do arquivo.</li><li><b>Impressora de uma cor só:</b> imprima por cor. Depois encaixe ou cole.</li><li><b>Impressora com sistema de cores:</b> dá pra imprimir tudo junto, escolhendo a cor de cada peça.</li><li><b>Cola:</b> cola instantânea (tipo Super Bonder) funciona bem em PLA.</li></ul></>],
            ["Configurações seguras pra começar",<><p>O perfil padrão do programa pra sua impressora já funciona. Se quiser um ponto de partida:</p><div className="grid gap-2 sm:grid-cols-2">{[["Filamento","PLA"],["Altura de camada","0,20 mm"],["Preenchimento","15%"],["Paredes","2 a 3"],["Suporte","Só se precisar"],["Aderência","Borda (brim) em peças altas ou finas"]].map(([k,v])=><div key={k} className="flex justify-between gap-4 rounded-lg bg-[#f5f8fc] p-3"><span className="text-zinc-400">{k}</span><b>{v}</b></div>)}</div><p className="rounded-xl bg-amber-400/10 p-3 text-sm text-amber-200">⚠️ Articulados e “imprime pronto” (print-in-place): não mude muito a escala nem ligue suporte. As juntas foram desenhadas pra soltar na medida certa.</p></>],
            ["Deu problema? Soluções rápidas",<div className="space-y-3">{[["A peça não gruda na mesa","Limpe a mesa com álcool isopropílico, faça o nivelamento e use borda (brim)."],["Abriu só uma parte do modelo","Veja as outras placas no topo do programa. Se abrir só a primeira, fale com a gente que mandamos em .STL separado."],["A peça é maior que a minha mesa","Diminua a escala (ex.: 80%) ou gire a peça. Evite mexer na escala de articulados."],["Fios de plástico entre as partes","É o stringing: geralmente filamento úmido ou temperatura alta. Abaixe uns 5 °C e guarde o filamento fechado."],["A articulação ficou travada","Mexa com cuidado logo depois de imprimir, ainda morna. Se não soltar, confira se o suporte estava desligado."],["O arquivo não abre","Se for .zip, descompacte primeiro. Se for .3mf, use Abrir projeto. Ainda não abriu? Chama a gente no Suporte."]].map(([q,a])=><div key={q}><b>{q}</b><p>{a}</p></div>)}</div>],
            ["Dicionário do iniciante",<div className="grid gap-3 sm:grid-cols-2">{[["Fatiador","Programa que transforma a peça em camadas e prepara a impressão."],["Fatiar","O momento em que o programa calcula as camadas, o tempo e o filamento."],["G-code","O arquivo final, já fatiado, que a impressora entende."],["Placa (plate)","Cada mesa de impressão dentro de um projeto .3mf."],["Suporte","Estrutura provisória que segura partes no ar. Sai depois de imprimir."],["Preenchimento (infill)","O recheio de dentro da peça. Mais preenchimento = peça mais firme e mais filamento."],["Borda (brim)","Contorno fino em volta da peça pra ela grudar melhor na mesa."],["Print-in-place","Peça articulada que já sai montada da impressora."]].map(([q,a])=><div key={q} className="rounded-xl bg-white/[.035] p-3"><b>{q}</b><p>{a}</p></div>)}</div>]
          ].map(([name,body],i)=><section id={`guide-${i+1}`} key={String(name)} className={`${panel} scroll-mt-24 p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-widest text-[#f28c28]">PASSO {i+1}</p><h3 className="mb-4 mt-2 text-xl font-extrabold">{name}</h3><div className="space-y-3 leading-7 text-zinc-300 [&_li]:text-zinc-300 [&_p]:leading-7">{body}</div></section>)}
          <section className={`${panel} flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between`}><div><h3 className="text-xl font-extrabold">Travou em algum passo?</h3><p className="mt-2 text-zinc-400">Manda a dúvida pra gente com o nome do modelo e a sua impressora.</p></div><button onClick={()=>jump("Suporte")} className={button}>✉ IR PARA O SUPORTE</button></section></div>}
        {section==="Início" && <div className="space-y-8 animate-in fade-in duration-300">
          <section id="novidades" className="overflow-hidden rounded-3xl border border-[#dce5ef] bg-white shadow-[0_16px_50px_rgba(18,56,90,.08)]">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#dce5ef] bg-[#f5f8fc] px-5 py-4 sm:px-7">
              <div><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">ATUALIZADA TODA SEMANA</p><p className="mt-1 text-sm font-bold text-[#17324d]">+2.309 arquivos adicionados nos últimos 28 dias</p></div>
              <button onClick={()=>jump("Bônus")} className={button}>VER NOVIDADES →</button>
            </div>
            <div className="grid gap-8 bg-[#12385a] px-6 py-9 text-[#17324d] sm:px-10 sm:py-12 lg:grid-cols-[1.2fr_.8fr] lg:items-center">
              <div><span className="inline-flex rounded-full border border-white/20 bg-white/10 px-3 py-1.5 text-[10px] font-black uppercase tracking-[.16em] text-[#17324d]">ACESSO LIBERADO</span><p className="mt-5 text-xs font-black uppercase tracking-[.2em] text-[#ffad55]">PRIME PROJETOS 3D</p><h2 className="mt-3 max-w-3xl text-4xl font-black leading-[1.08] tracking-tight text-[#17324d] sm:text-5xl">Sua impressora 3D agora tem o que imprimir.</h2><p className="mt-5 max-w-2xl text-base leading-7 text-blue-50/90">Mais de <b className="text-[#17324d]">100 mil arquivos STL</b> prontos, testados e organizados pelo que mais vende. É só baixar, imprimir e vender, <b className="text-[#17324d]">sem modelar nada.</b></p><div className="mt-7 flex flex-wrap gap-3"><button onClick={()=>document.getElementById("biblioteca-inicio")?.scrollIntoView({behavior:"smooth"})} className={button}>EXPLORAR BIBLIOTECA ↓</button><button onClick={()=>jump("Leia antes de começar")} className="rounded-xl border border-white/25 px-4 py-3 text-sm font-extrabold text-[#17324d] transition hover:bg-white/10">COMO FUNCIONA</button></div></div>
              <div className="grid grid-cols-2 gap-3">{[["+100 mil","arquivos STL"],["1.052","módulos e modelos"],["30","categorias"],["+2.309","novos em 28 dias"]].map(([n,t])=><div key={t} className="rounded-2xl border border-white/15 bg-white/10 p-4 sm:p-5"><p className="text-2xl font-black tracking-tight text-[#ffad55] sm:text-3xl">{n}</p><p className="mt-2 text-xs font-semibold leading-5 text-blue-50/90">{t}</p></div>)}</div>
            </div>
            <div className="flex flex-wrap items-center gap-x-3 gap-y-2 bg-[#fff7ef] px-5 py-4 text-sm text-[#17324d] sm:px-7"><b className="text-[#f28c28]">NESTA SEMANA:</b><span>Seção Católica, Especial de Natal, Pack de Luminárias e Templates.</span></div>
          </section>

          <section className="space-y-4"><div className="text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">VANTAGENS EXTRAS</p><h2 className="mt-2 text-2xl font-black tracking-tight text-[#17324d] sm:text-3xl">Além dos arquivos, você também recebe</h2><p className="mt-2 text-sm text-[#60758a]">Ferramentas e materiais para produzir melhor e transformar impressões em vendas.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            {[["🎄","Templates de Natal","Artes e materiais para preparar suas divulgações da temporada.","VER BÔNUS","Bônus"],["🧮","Calculadora e precificação","Calcule custo, filamento, tempo de máquina e preço de venda.","ABRIR CALCULADORA","Calculadora"],["👥","Comunidade de impressão 3D","Encontre grupos para trocar experiências, ideias e modelos.","ACESSAR COMUNIDADE","Comunidade"],["📊","Painel de vendas","Registre faturamento, despesas, estoque e acompanhe suas metas.","ABRIR PAINEL","Administração"]].map(([ic,t,d,b,dest])=><article key={t} className="rounded-2xl border border-[#dce5ef] bg-white p-5 shadow-[0_8px_28px_rgba(18,56,90,.05)] transition hover:-translate-y-1 hover:border-[#f28c28]/50"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#fff1e4] text-2xl">{ic}</span><h3 className="mt-4 text-lg font-extrabold text-[#17324d]">{t}</h3><p className="mt-2 min-h-12 text-sm leading-6 text-[#60758a]">{d}</p><button onClick={()=>jump(dest)} className="mt-4 text-xs font-black tracking-wide text-[#e87513] hover:underline">{b} →</button></article>)}
          </div></section>

          <section className="overflow-hidden rounded-3xl border border-[#dce5ef] bg-white shadow-[0_12px_40px_rgba(18,56,90,.06)]">
            <div className="grid gap-6 p-5 sm:p-8 lg:grid-cols-[.72fr_1.28fr] lg:items-center">
              <div className="overflow-hidden rounded-2xl bg-[#f1f5f9]"><img src="https://img.taidon.app/3d/guia-capa.webp" alt="Capa do Guia Definitivo de Impressão 3D" loading="lazy" className="mx-auto max-h-[420px] w-full object-contain"/></div>
              <div><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">GUIA EM PDF · 30 PÁGINAS</p><h2 className="mt-2 text-3xl font-black tracking-tight text-[#17324d]">Guia Definitivo de Impressão 3D</h2><p className="mt-3 leading-7 text-[#60758a]">Do download à peça perfeita: aprenda sobre fatiador, camadas, suportes, erros comuns e acabamento. Um passo a passo para acompanhar desde a escolha do arquivo até a finalização da peça.</p><div className="mt-5 grid gap-2 sm:grid-cols-3">{[["01","Prepare o computador"],["02","Baixe seu arquivo"],["03","Prepare e imprima"]].map(([n,t])=><div key={n} className="rounded-xl bg-[#f5f8fc] p-3"><span className="text-xs font-black text-[#f28c28]">{n}</span><p className="mt-1 text-sm font-bold text-[#17324d]">{t}</p></div>)}</div><div className="mt-6 flex flex-wrap gap-3"><a href="https://bibliotecamakerpro-membros.netlify.app/guia/guia-definitivo-impressao-3d.pdf" target="_blank" rel="noreferrer" className={button}>BAIXAR GUIA EM PDF ↓</a><a href="https://bibliotecamakerpro-membros.netlify.app/guia/guia-definitivo-impressao-3d.pdf" target="_blank" rel="noreferrer" className="inline-flex items-center rounded-xl border border-[#dce5ef] px-4 py-3 text-sm font-extrabold text-[#17324d] transition hover:border-[#f28c28]">ABRIR NO NAVEGADOR ↗</a></div><p className="mt-3 text-xs text-[#8293a5]">30 páginas · Consulte o mapa de assuntos e avance direto para cada etapa.</p></div>
            </div>
          </section>

          <section id="biblioteca-inicio" className="scroll-mt-24"><div className="mb-5 text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">EXPLORE OS MÓDULOS</p><h2 className="mt-2 text-3xl font-black tracking-tight text-[#17324d]">Biblioteca completa de arquivos</h2><p className="mt-2 text-sm text-[#60758a]">Escolha uma categoria e acesse as pastas organizadas no Google Drive.</p></div><div className="mb-5 flex flex-col items-center gap-3 sm:flex-row sm:justify-center"><span className="text-center text-xs font-black tracking-widest text-[#f28c28]">{categories.length} CATEGORIAS DISPONÍVEIS</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar entre as categorias..." className={field+" sm:max-w-xs"}/></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(([name,desc,icon,url],i)=><article key={name} className="group overflow-hidden rounded-2xl border border-[#dce5ef] bg-white shadow-[0_8px_24px_rgba(18,56,90,.05)] transition-all duration-200 hover:-translate-y-1 hover:border-[#f28c28]/50"><div className="relative h-40 overflow-hidden bg-[#eef3f8] sm:h-44">{categoryImages[name] ? <img src={categoryImages[name]} alt={"Prévia da categoria "+name} loading="lazy" decoding="async" className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.04]"/> : <div className="flex h-full w-full flex-col items-center justify-center gap-3 text-[#f28c28]"><span className="text-5xl">{icon}</span><span className="text-[10px] font-black uppercase tracking-[.2em] text-[#8293a5]">Imagem em breve</span></div>}<div className="absolute inset-0 bg-gradient-to-t from-[#12385a]/35 to-transparent"/></div><div className="p-4"><div className="flex justify-center"><span className="rounded-full bg-[#edf5fc] px-3 py-1 text-[9px] font-black tracking-widest text-[#28577f]">ARQUIVOS ORGANIZADOS</span></div><h3 className="mt-3 text-center text-lg font-extrabold text-[#17324d]">{name}</h3><p className="mt-2 min-h-10 text-center text-sm leading-5 text-[#60758a]">{desc}</p>{name==="Natal"&&<p className="mt-3 text-center text-xs font-bold text-[#e87513]">✨ ESPECIAL DE NATAL</p>}{categoryExtraLinks[name] ? <div className="mt-4 grid grid-cols-2 gap-2">{categoryExtraLinks[name].map(link=><a key={link.url} href={link.url} target="_blank" rel="noreferrer" className={button+" w-full px-2 text-xs"}>{link.label} ↗</a>)}</div> : <a href={url} target="_blank" rel="noreferrer" className={button+" mt-4 w-full"}>ACESSAR ARQUIVOS ↗</a>}</div></article>)}</div></section>

          <section className="rounded-3xl border border-[#dce5ef] bg-white p-5 shadow-[0_8px_28px_rgba(18,56,90,.05)] sm:p-8"><div className="text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#f28c28]">CENTRAL DE AJUDA</p><h2 className="mt-2 text-2xl font-black text-[#17324d] sm:text-3xl">Dúvidas rápidas</h2><p className="mt-2 text-sm text-[#60758a]">Respostas para começar a usar sua biblioteca sem complicação.</p></div><div className="mx-auto mt-6 max-w-4xl divide-y divide-[#e5ebf2]">{[["Preciso baixar os 100 mil arquivos de uma vez?","Não. Tudo fica organizado por módulo. Você abre a pasta e baixa só o que for imprimir."],["O arquivo não abriu ou deu erro no fatiador. E agora?","Primeiro confirme que descompactou o .zip com o WinRAR. Se o fatiador mostrar um aviso de erro, clique em Reparar e aguarde até o fim. Depois é só fatiar de novo."],["Meu modelo veio com mais de um arquivo.","Alguns modelos têm o corpo e as partes, por exemplo olhos e nariz. Importe o corpo e depois as partes no mesmo projeto. Imprimir tudo junto é opcional: você pode imprimir uma peça de cada vez."],["Preciso usar suporte na impressão?","Depende da peça. Peças maiores ou sem uma base firme costumam precisar. No fatiador, ative Habilitar suporte e fatie; se o suporte ficar desnecessário, desmarque e fatie de novo."],["Posso vender o que eu imprimir?","Pode imprimir e vender as peças físicas, respeitando a licença aplicável a cada modelo. Confira sempre as permissões do criador e os direitos de marcas e personagens de terceiros."]].map(([q,a])=><details key={q} className="group py-4"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-bold text-[#17324d] marker:hidden">{q}<span className="text-xl font-black text-[#f28c28] transition group-open:rotate-45">+</span></summary><p className="mt-3 max-w-3xl pr-8 text-sm leading-7 text-[#60758a]">{a}</p></details>)}</div></section>
        </div>}
        {section==="Biblioteca 3D" && <div className="animate-in fade-in duration-300">{heading("BIBLIOTECA EXCLUSIVA","Biblioteca 3D","Modelos organizados por categoria, prontos pra fatiar.")}<section className={`${panel} mb-5 border-[#f28c28]/25 p-4 sm:p-5`}><p className="text-sm leading-6 text-zinc-300">📂 <b>Arquivos prontos e organizados por categoria, não são modelos inéditos.</b> Muitos vêm de repositórios abertos (MakerWorld, Printables, Thingiverse). O nosso trabalho foi reunir, separar e organizar tudo pra você imprimir sem perder tempo procurando.</p></section><div className="mb-5 flex flex-col items-center gap-3 sm:flex-row sm:justify-center"><span className="text-center text-xs font-black tracking-widest text-[#f28c28]">ARQUIVOS ORGANIZADOS · {filtered.length} CATEGORIAS</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar entre as categorias..." className={`${field} sm:max-w-xs`}/></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(([name,desc,icon,url],i)=><article key={name} className={`${panel} group overflow-hidden transition-all duration-200 hover:-translate-y-1 hover:border-[#f28c28]/40`}><div className="relative h-44 overflow-hidden bg-[#f5f8fc] sm:h-48">{categoryImages[name] ? <img src={categoryImages[name]} alt={"Prévia da categoria " + name} loading="eager" decoding="async" className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.04]"/> : <div className="flex h-full w-full flex-col items-center justify-center gap-3 bg-[radial-gradient(ellipse_at_center,_rgba(242,140,40,0.10),_transparent_65%)] text-[#f28c28]"><span className="text-5xl opacity-90">{icon}</span><span className="text-[10px] font-black uppercase tracking-[.2em] text-zinc-500">Imagem em breve</span></div>}<div className="absolute inset-0 bg-gradient-to-t from-[#151515]/75 via-transparent to-black/10"/></div><div className="h-1 bg-[#f28c28] opacity-70 transition group-hover:opacity-100"/><div className="p-5"><div className="flex justify-center"><span className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-3 py-1 text-[9px] font-black tracking-widest text-emerald-300">ARQUIVOS ORGANIZADOS</span></div><h3 className="mt-4 text-center text-lg font-extrabold">{name}</h3><p className="mt-2 min-h-10 text-center text-sm leading-5 text-zinc-400">{desc}</p>{name.startsWith("Natal")&&<p className="mt-3 text-xs font-bold text-[#f28c28]">✨ 11 NOVOS · 21 ARQUIVOS</p>}{name.startsWith("Brinquedos Sensoriais")&&<p className="mt-3 text-xs font-bold text-[#f28c28]">✨ 16 NOVOS</p>}{categoryExtraLinks[name] ? <div className="mt-5 grid grid-cols-2 gap-2">{categoryExtraLinks[name].map(link=><a key={link.url} href={link.url} target="_blank" rel="noreferrer" className={`${button} w-full px-2 text-xs`}>{link.label} ↗</a>)}</div> : <a href={url} target="_blank" rel="noreferrer" className={`${button} mt-5 w-full`}>{i===1?"VER 21 ARQUIVOS":"ACESSAR ARQUIVOS"} ↗</a>}</div></article>)}</div></div>}
        {section==="Comunidade" && <div className="animate-in fade-in duration-300">
          {heading("COMUNIDADE","Comunidade no Telegram","Troque ideias e modelos com outros makers.")}
          <section className={`${panel} mx-auto max-w-2xl p-6 text-center sm:p-8`}>
            <img src="/comunidade-telegram.webp" alt="Comunidade Impressão 3D no Telegram" className="mx-auto h-48 w-48 rounded-full object-cover sm:h-56 sm:w-56"/>
            <p className="mx-auto mt-6 max-w-lg leading-7 text-zinc-300">Entre em grupos com milhares de pessoas que compartilham dicas, tiram dúvidas e trocam modelos de impressão 3D. São comunidades independentes, não administradas pela Prime Projetos 3D.</p>
            <div className="mt-6 grid gap-3 sm:grid-cols-3">
              {[["GRUPO 1","https://t.me/torrentstl/1"],["GRUPO 2","https://t.me/redestlbrasil"],["GRUPO 3","https://t.me/impressao3dbrasill"]].map(([n,u])=><a key={n} href={u} target="_blank" rel="noreferrer" className={`${button} w-full`}>{n} ↗</a>)}
            </div>
          </section>
        </div>}
        {section==="Calculadora" && <div className="animate-in fade-in duration-300">{heading("FERRAMENTA OFICIAL","Calculadora de Custos","Descubra quanto custa cada impressão e por quanto vender.")}<div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><section className={`${panel} p-5 sm:p-6`}><div className="mb-5 flex items-center justify-between gap-3"><h3 className="text-lg font-extrabold">Dados da peça</h3><button onClick={()=>{setWeight("120");setRoll("90");setHours("4");setHourCost("1.5");setWaste("10");setProfit("70");setFee("20")}} className="text-xs font-bold text-[#f28c28] hover:underline">Preencher exemplo (120g)</button></div><div className="grid gap-4 sm:grid-cols-2"><label><span className={label}>Peso da peça (g) *</span><input type="number" min="0" value={weight} onChange={e=>setWeight(e.target.value)} className={field}/><small className="mt-1 block text-zinc-600">Gramas no slicer</small></label><label><span className={label}>Preço do rolo 1kg (R$) *</span><input type="number" min="0" value={roll} onChange={e=>setRoll(e.target.value)} className={field}/><small className="mt-1 block text-zinc-600">Valor pago por 1.000g</small></label><label><span className={label}>Tempo de impressão (h)</span><input type="number" min="0" step=".1" value={hours} onChange={e=>setHours(e.target.value)} className={field}/><small className="mt-1 block text-zinc-600">Duração no slicer</small></label><label><span className={label}>Custo da hora (R$/h)</span><input type="number" min="0" step=".1" value={hourCost} onChange={e=>setHourCost(e.target.value)} className={field}/><small className="mt-1 block text-zinc-600">Energia + desgaste</small></label></div><h4 className="mb-3 mt-7 font-extrabold">Margens</h4><div className="grid gap-4 sm:grid-cols-3">{[["Reserva p/ falhas (%)",waste,setWaste],["Lucro desejado (%)",profit,setProfit],["Taxa do marketplace (%)",fee,setFee]].map(([t,v,set])=><label key={String(t)}><span className={label}>{t as string}</span><input type="number" min="0" value={v as string} onChange={e=>(set as (v:string)=>void)(e.target.value)} className={field}/></label>)}</div></section><section className={`${panel} h-fit border-[#f28c28]/25 p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-widest text-[#f28c28]">RESULTADO EM TEMPO REAL</p><h3 className="mt-3 text-xl font-extrabold">Preço sugerido da peça</h3><p className="mt-5 text-4xl font-black tracking-tight text-[#f28c28]">{Number(weight)>0&&Number(roll)>0?money(price):"Aguardando dados"}</p><p className="mt-2 text-sm text-zinc-500">Preço de venda sugerido com margem e taxa incluídas.</p><div className="my-5 h-px bg-white/10"/><div className="space-y-3 text-sm"><div className="flex justify-between gap-3"><span className="text-zinc-400">Filamento + reserva</span><b>{money((Number(weight)||0)/1000*(Number(roll)||0)*(1+(Number(waste)||0)/100))}</b></div><div className="flex justify-between gap-3"><span className="text-zinc-400">Energia + desgaste</span><b>{money((Number(hours)||0)*(Number(hourCost)||0))}</b></div><div className="flex justify-between gap-3"><span className="text-zinc-400">Custo total estimado</span><b>{money(cost)}</b></div><div className="flex justify-between gap-3 border-t border-white/10 pt-3"><span className="text-zinc-400">Lucro estimado</span><b className="text-emerald-300">{money(price*(1-(Number(fee)||0)/100)-cost)}</b></div></div><p className="mt-5 rounded-xl bg-[#fff7ef] p-3 text-xs leading-5 text-zinc-400">Estimativa inicial. Considere também embalagem, mão de obra e outros custos específicos do seu negócio.</p></section></div></div>}
        {section==="Administração" && <div className="animate-in fade-in duration-300">{heading("PAINEL DA EMPRESA","Administração","Seus dados ficam salvos neste navegador. Preencha os campos para acompanhar seus números.")}<div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Faturamento",money(Number(sales)||0),"Receita registrada"],["Custos",money((Number(expenses)||0)+(Number(productCost)||0)),"Despesas + peças"],["Lucro",money((Number(sales)||0)-(Number(expenses)||0)-(Number(productCost)||0)),"Lucro calculado"],["Estoque",`${Number(filament||0).toFixed(2).replace(".",",")} kg`,"Filamento disponível"]].map(([k,v,d])=><div key={k} className={`${panel} p-5`}><p className="text-sm text-zinc-500">{k}</p><p className="mt-3 text-2xl font-black">{v}</p><p className="mt-1 text-xs text-zinc-500">{d}</p></div>)}</div><section className={`${panel} p-5 sm:p-6`}><div className="flex flex-wrap gap-2 border-b border-white/10 pb-4">{["Visão geral","Vendas","Despesas","Produtos","Filamentos","Metas"].map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg px-3 py-2 text-sm font-bold transition ${tab===t?"bg-[#f28c28] text-black":"text-zinc-400 hover:bg-white/5 hover:text-[#17324d]"}`}>{t}</button>)}</div>{tab==="Visão geral"||tab==="Metas"?<div className="mt-5"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-lg font-extrabold">Meta de faturamento</h3><b className="text-[#f28c28]">{Math.min(100,Math.round((Number(sales)||0)/(Number(target)||1)*100))}%</b></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-[#f28c28] transition-all" style={{width:`${Math.min(100,Math.max(0,(Number(sales)||0)/(Number(target)||1)*100))}%`}}/></div><div className="mt-2 flex justify-between gap-2 text-sm text-zinc-400"><span>{money(Number(sales)||0)} faturados</span><label className="flex items-center gap-2">Meta <input type="number" value={target} onChange={e=>setTarget(e.target.value)} className="w-32 rounded-lg border border-white/10 bg-black px-2 py-1 text-[#17324d]"/></label></div></div>:null}<div className="mt-6 grid gap-4 sm:grid-cols-2">{[["Vendas / faturamento (R$)",sales,setSales],["Despesas (R$)",expenses,setExpenses],["Custo de peças (R$)",productCost,setProductCost],["Estoque de filamento (kg)",filament,setFilament]].map(([t,v,set])=><label key={String(t)}><span className={label}>{t as string}</span><input type="number" min="0" value={v as string} onChange={e=>(set as (v:string)=>void)(e.target.value)} className={field}/></label>)}</div><p className="mt-4 text-xs leading-5 text-zinc-500">Esta versão mantém os valores enquanto a página estiver aberta; armazenamento persistente entre sessões ainda precisa ser conectado.</p><button onClick={()=>{setSales("0");setExpenses("0");setProductCost("0");setFilament("0");setTarget("10000")}} className="mt-4 rounded-xl border border-white/10 px-4 py-2.5 text-sm font-bold text-zinc-400 transition hover:border-red-400/40 hover:text-red-300">Resetar dados</button></section></div>}
        {section==="Bônus" && <div className="animate-in fade-in duration-300">{heading("CONTEÚDO EXTRA","Seus Bônus","Materiais extras para precificar, produzir melhor, fotografar e vender.")}<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{bonus.map(([icon,name,desc,url])=><article key={name} className={`${panel} group overflow-hidden transition duration-200 hover:-translate-y-1 hover:border-[#f28c28]/35`}><div className="h-1 bg-[#f28c28]"/><div className="p-5"><div className="flex justify-center"><span className="rounded-full border border-[#f28c28]/20 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-[#f28c28]">BÔNUS EXCLUSIVO</span></div><h3 className="mt-4 text-center text-lg font-extrabold">{name}</h3><p className="mt-2 min-h-12 text-center text-sm leading-6 text-zinc-400">{desc}</p><a href={url} target={url.startsWith("http")?"_blank":undefined} rel={url.startsWith("http")?"noreferrer":undefined} className={`${button} mt-5 w-full`}>ACESSAR ↗</a></div></article>)}</div></div>}
        {section==="Licença Comercial" && <div className="animate-in fade-in duration-300">{heading("TERMOS DE USO","Licença Comercial","Termos de uso dos arquivos da biblioteca.")}<section className={`${panel} max-w-4xl p-5 sm:p-7`}><div className="flex items-center gap-3 border-b border-white/10 pb-5"><span className="grid h-12 w-12 place-items-center rounded-xl bg-[#f28c28]/10 text-2xl">📜</span><div><p className="text-xs font-black uppercase tracking-widest text-[#f28c28]">IMPRIMIR</p><h3 className="text-xl font-black">Licença Comercial PRIME <span className="text-[#f28c28]">PROJETOS 3D</span></h3></div></div><div className="mt-6 space-y-6 leading-7 text-zinc-300"><div><h4 className="font-extrabold text-[#17324d]">1. O que você recebe</h4><p>Uma licença pessoal, não exclusiva e intransferível para imprimir os modelos da biblioteca e vender as peças físicas impressas.</p></div><div><h4 className="font-extrabold text-[#17324d]">2. O que é permitido</h4><ul className="mt-2 list-disc space-y-1 pl-5"><li>Imprimir os modelos para uso próprio ou para venda das peças físicas.</li><li>Vender as peças impressas em lojas, redes sociais, marketplaces, feiras e encomendas.</li><li>Usar fotos e vídeos das suas peças impressas para divulgar.</li></ul></div><div><h4 className="font-extrabold text-[#17324d]">3. O que não é permitido</h4><ul className="mt-2 list-disc space-y-1 pl-5"><li>Revender, compartilhar ou distribuir os arquivos digitais (STL, 3MF, OBJ), pagos ou grátis.</li><li>Publicar os arquivos em grupos, drives, sites, torrents ou plataformas de modelos.</li><li>Apresentar os arquivos como criação sua.</li></ul></div><div className="rounded-xl border border-amber-300/20 bg-amber-300/[.06] p-4"><h4 className="font-extrabold text-amber-200">Personagens e marcas de terceiros</h4><p className="mt-1 text-sm">A biblioteca não inclui personagens nem marcas registradas. Se você imprimir peças de personagens de outras fontes, a responsabilidade por direitos autorais e de marca é sua.</p></div></div></section></div>}
        {section==="Suporte" && <div className="animate-in fade-in duration-300">{heading("ATENDIMENTO","Suporte","Canal oficial de atendimento. Estamos aqui para ajudar você a começar.")}<section className={`${panel} max-w-3xl overflow-hidden border-[#f28c28]/25`}><div className="h-1.5 bg-[#f28c28]"/><div className="p-6 sm:p-8"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-[#f28c28]/10 text-3xl">✉</span><h3 className="mt-5 text-2xl font-black">Precisa de uma mão?</h3><p className="mt-3 leading-7 text-zinc-400">Não achou algo, um link não abre ou ficou em dúvida sobre como imprimir ou precificar? Manda a dúvida pra gente com o nome do modelo e a sua impressora.</p><div className="mt-6 flex flex-wrap gap-3"><button onClick={()=>navigator.clipboard?.writeText("botelhoenzo7@gmail.com")} className={button}>✉ COPIAR E-MAIL</button></div><p className="mt-4 text-xs text-zinc-600">E-mail de contato: botelhoenzo7@gmail.com</p></div></section></div>}
      </div>
      <footer className="border-t border-white/[.07] px-5 py-5 text-center text-xs text-zinc-600">PRIME PROJETOS 3D <span className="mx-2 text-[#f28c28]">•</span> Organize. Imprima. Venda.</footer>
    </main>
  </div>;
}
